CREATE OR REPLACE FUNCTION public.create_booking_with_wallet_payment(p_user_id uuid, p_booking_type text, p_scheduled_at timestamp with time zone, p_total_amount numeric, p_currency text, p_provider_id uuid DEFAULT NULL::uuid, p_service_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wallet_id UUID;
  v_balance NUMERIC;
  v_booking_id UUID;
BEGIN
  -- Get wallet and lock row
  SELECT id, balance INTO v_wallet_id, v_balance
  FROM wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found';
  END IF;

  IF v_balance < p_total_amount THEN
    RAISE EXCEPTION 'Insufficient balance';
  END IF;

  -- Create booking first
  INSERT INTO bookings (
    user_id, booking_type, status, scheduled_at, 
    total_amount, currency, provider_id, service_id, notes
  ) VALUES (
    p_user_id, p_booking_type::booking_type, 'confirmed', p_scheduled_at,
    p_total_amount, p_currency, p_provider_id, p_service_id, p_notes
  )
  RETURNING id INTO v_booking_id;

  -- Deduct from wallet
  UPDATE wallets 
  SET balance = balance - p_total_amount, updated_at = now()
  WHERE id = v_wallet_id;

  -- Record transaction
  INSERT INTO wallet_transactions (wallet_id, user_id, amount, type, description, status, reference_id)
  VALUES (v_wallet_id, p_user_id, -p_total_amount, 'payment', 'Booking payment', 'completed', v_booking_id);

  -- Record payment
  INSERT INTO booking_payments (booking_id, amount, payment_method, status, paid_at, currency)
  VALUES (v_booking_id, p_total_amount, 'wallet', 'completed', now(), p_currency);

  RETURN v_booking_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_order_atomic(p_order_type text, p_customer_user_id uuid, p_provider_org_id uuid DEFAULT NULL::uuid, p_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_total_amount numeric DEFAULT 0, p_currency text DEFAULT 'THB'::text, p_notes text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_items jsonb DEFAULT '[]'::jsonb, p_participants jsonb DEFAULT '[]'::jsonb, p_addresses jsonb DEFAULT '[]'::jsonb, p_payment_method text DEFAULT NULL::text, p_payment_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id UUID;
  v_order_number TEXT;
  v_item JSONB;
  v_participant JSONB;
  v_address JSONB;
BEGIN
  -- Create order
  INSERT INTO public.orders (
    order_type, customer_user_id, provider_org_id,
    status, start_at, end_at, total_amount, currency, notes, metadata
  ) VALUES (
    p_order_type, p_customer_user_id, p_provider_org_id,
    'pending', p_start_at, p_end_at, p_total_amount, p_currency, p_notes, p_metadata
  )
  RETURNING id, order_number INTO v_order_id, v_order_number;

  -- Insert items
  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      INSERT INTO public.order_items (
        order_id, product_id, resource_id, provider_org_id,
        item_name, item_type, qty, unit_price, amount, 
        start_at, end_at, metadata
      ) VALUES (
        v_order_id,
        NULLIF(v_item->>'product_id', '')::uuid,
        NULLIF(v_item->>'resource_id', '')::uuid,
        COALESCE(NULLIF(v_item->>'provider_org_id', '')::uuid, p_provider_org_id),
        v_item->>'item_name',
        COALESCE(v_item->>'item_type', 'service'),
        COALESCE((v_item->>'qty')::int, 1),
        COALESCE((v_item->>'unit_price')::numeric, 0),
        COALESCE((v_item->>'amount')::numeric, 0),
        NULLIF(v_item->>'start_at', '')::timestamptz,
        NULLIF(v_item->>'end_at', '')::timestamptz,
        COALESCE(v_item->'metadata', '{}'::jsonb)
      );
    END LOOP;
  END IF;

  -- Insert participants
  IF p_participants IS NOT NULL AND jsonb_array_length(p_participants) > 0 THEN
    FOR v_participant IN SELECT * FROM jsonb_array_elements(p_participants)
    LOOP
      INSERT INTO public.order_participants (
        order_id, role, name, phone, email
      ) VALUES (
        v_order_id,
        COALESCE(v_participant->>'role', 'primary'),
        v_participant->>'name',
        v_participant->>'phone',
        v_participant->>'email'
      );
    END LOOP;
  END IF;

  -- Insert addresses
  IF p_addresses IS NOT NULL AND jsonb_array_length(p_addresses) > 0 THEN
    FOR v_address IN SELECT * FROM jsonb_array_elements(p_addresses)
    LOOP
      INSERT INTO public.order_addresses (
        order_id, address_type, address_text, lat, lng, notes
      ) VALUES (
        v_order_id,
        v_address->>'address_type',
        v_address->>'address_text',
        NULLIF(v_address->>'lat', '')::numeric,
        NULLIF(v_address->>'lng', '')::numeric,
        v_address->>'notes'
      );
    END LOOP;
  END IF;

  -- Create payment intent if provided (cast text to payment_method enum)
  IF p_payment_method IS NOT NULL AND p_payment_amount IS NOT NULL THEN
    INSERT INTO public.payment_intents (
      order_id, amount, currency, method, status
    ) VALUES (
      v_order_id, p_payment_amount, p_currency, p_payment_method::payment_method, 'pending'
    );
  END IF;

  -- Record initial status in history
  INSERT INTO public.order_status_history (
    order_id, from_status, to_status, actor_user_id, reason
  ) VALUES (
    v_order_id, NULL, 'pending', p_customer_user_id, 'Order created'
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'order_number', v_order_number
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_property_booking_from_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_property_id uuid;
  v_owner_id uuid;
  v_guest_name text;
  v_guest_phone text;
  v_guest_email text;
  v_check_in date;
  v_check_out date;
  v_source text;
  v_source_calendar_id uuid;
BEGIN
  -- Only for property vertical orders that become confirmed
  IF NEW.vertical != 'property' THEN
    RETURN NEW;
  END IF;

  IF NEW.status != 'confirmed' THEN
    RETURN NEW;
  END IF;

  -- Skip if already confirmed before (update case)
  IF OLD IS NOT NULL AND OLD.status = 'confirmed' THEN
    RETURN NEW;
  END IF;

  -- Get property_id from order_items metadata
  SELECT (oi.metadata->>'property_id')::uuid
  INTO v_property_id
  FROM order_items oi 
  WHERE oi.order_id = NEW.id AND oi.item_type = 'property'
  LIMIT 1;

  IF v_property_id IS NULL THEN
    RETURN NEW; -- no property linked, skip
  END IF;

  -- Get owner_id from owner_properties
  SELECT op.owner_id INTO v_owner_id
  FROM owner_properties op WHERE op.id = v_property_id;

  IF v_owner_id IS NULL THEN
    RETURN NEW; -- property not found in owner_properties, skip
  END IF;

  -- Get guest info from order_participants
  SELECT p.name, p.phone, p.email
  INTO v_guest_name, v_guest_phone, v_guest_email
  FROM order_participants p
  WHERE p.order_id = NEW.id AND p.role = 'guest'
  LIMIT 1;

  -- Fallback to metadata
  IF v_guest_name IS NULL THEN
    v_guest_name := NEW.metadata->>'guest_name';
  END IF;

  -- Dates from order
  v_check_in := (NEW.start_at AT TIME ZONE 'Asia/Bangkok')::date;
  v_check_out := (NEW.end_at AT TIME ZONE 'Asia/Bangkok')::date;

  IF v_check_in IS NULL OR v_check_out IS NULL THEN
    RETURN NEW;
  END IF;

  -- Source info
  v_source := COALESCE(NEW.metadata->>'source', 'manual');
  v_source_calendar_id := (NEW.metadata->>'source_calendar_id')::uuid;

  -- Insert booking, skip if already exists for this order
  INSERT INTO property_bookings (
    property_id, owner_id, guest_name, guest_phone, guest_email,
    check_in, check_out, total_amount, currency, source,
    source_calendar_id, status, order_id, guest_id
  ) VALUES (
    v_property_id, v_owner_id, v_guest_name, v_guest_phone, v_guest_email,
    v_check_in, v_check_out, NEW.total_amount, COALESCE(NEW.currency, 'THB'), v_source,
    v_source_calendar_id, 'confirmed', NEW.id, NEW.customer_user_id
  )
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.credit_cashback(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order RECORD; v_set RECORD; v_amount NUMERIC; v_cur TEXT;
  v_wallet_acc UUID; v_platform_acc UUID; v_entry UUID; v_wallet UUID;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Order not found'); END IF;
  IF v_order.customer_user_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'No customer'); END IF;
  IF v_order.status <> 'completed' THEN RETURN jsonb_build_object('success', false, 'error', 'Order not completed'); END IF;
  IF EXISTS (SELECT 1 FROM ledger_entries WHERE order_id = p_order_id AND entry_type = 'cashback') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cashback already credited');
  END IF;
  SELECT * INTO v_set FROM cashback_settings WHERE category = v_order.vertical::text AND is_active LIMIT 1;
  IF NOT FOUND THEN SELECT * INTO v_set FROM cashback_settings WHERE category = 'default' AND is_active LIMIT 1; END IF;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'No cashback settings'); END IF;
  IF COALESCE(v_order.total_amount, 0) <= 0 OR v_order.total_amount < COALESCE(v_set.min_order_amount, 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order below minimum');
  END IF;
  v_amount := v_order.total_amount * (v_set.percentage / 100.0);
  IF v_set.max_cashback_amount IS NOT NULL AND v_amount > v_set.max_cashback_amount THEN v_amount := v_set.max_cashback_amount; END IF;
  v_amount := ROUND(v_amount, 2);
  IF v_amount <= 0 THEN RETURN jsonb_build_object('success', false, 'error', 'Cashback amount is zero'); END IF;
  v_cur := COALESCE(v_order.currency, 'THB');
  SELECT id INTO v_wallet_acc FROM ledger_accounts
   WHERE owner_user_id = v_order.customer_user_id AND account_type = 'user_wallet' AND currency = v_cur LIMIT 1;
  IF v_wallet_acc IS NULL THEN
    INSERT INTO ledger_accounts (owner_user_id, account_type, currency, balance)
    VALUES (v_order.customer_user_id, 'user_wallet', v_cur, 0) RETURNING id INTO v_wallet_acc;
  END IF;
  SELECT id INTO v_platform_acc FROM ledger_accounts
   WHERE account_type = 'platform_cashback' AND owner_user_id IS NULL AND owner_org_id IS NULL AND currency = v_cur LIMIT 1;
  IF v_platform_acc IS NULL THEN
    INSERT INTO ledger_accounts (account_type, currency, balance)
    VALUES ('platform_cashback', v_cur, 0) RETURNING id INTO v_platform_acc;
  END IF;
  INSERT INTO ledger_entries (debit_account_id, credit_account_id, amount, currency, order_id, entry_type, description)
  VALUES (v_platform_acc, v_wallet_acc, v_amount, v_cur, p_order_id, 'cashback',
          'Cashback for order ' || COALESCE(v_order.order_number, p_order_id::text))
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_entry;
  IF v_entry IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Cashback already credited'); END IF;
  UPDATE ledger_accounts SET balance = balance + v_amount, updated_at = now() WHERE id = v_wallet_acc;
  UPDATE ledger_accounts SET balance = balance - v_amount, updated_at = now() WHERE id = v_platform_acc;
  SELECT id INTO v_wallet FROM wallets WHERE user_id = v_order.customer_user_id AND currency = v_cur LIMIT 1;
  IF v_wallet IS NOT NULL THEN
    UPDATE wallets SET balance = balance + v_amount, updated_at = now() WHERE id = v_wallet;
    INSERT INTO wallet_transactions (wallet_id, user_id, type, amount, currency, description, description_ru, reference_type, reference_id, status)
    VALUES (v_wallet, v_order.customer_user_id, 'cashback', v_amount, v_cur,
            'Cashback for order', 'Кэшбэк за заказ', 'order', p_order_id::text, 'completed');
  END IF;
  RETURN jsonb_build_object('success', true, 'cashback_amount', v_amount, 'order_id', p_order_id, 'entry_id', v_entry);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_financial_to_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_mc_id uuid; v_expense_account_id uuid; v_owner_account_id uuid;
BEGIN
  IF NEW.reference_type = 'ledger_synced' THEN RETURN NEW; END IF;
  SELECT management_company_id INTO v_mc_id FROM properties WHERE id = NEW.property_id;
  IF v_mc_id IS NOT NULL THEN
    SELECT id INTO v_expense_account_id FROM ledger_accounts WHERE management_company_id = v_mc_id AND account_type = 'expense' AND is_active = true LIMIT 1;
    IF v_expense_account_id IS NULL THEN
      INSERT INTO ledger_accounts (account_type, management_company_id, currency) VALUES ('expense', v_mc_id, COALESCE(NEW.currency, 'THB')) RETURNING id INTO v_expense_account_id;
    END IF;
    SELECT id INTO v_owner_account_id FROM ledger_accounts WHERE owner_user_id = NEW.owner_id AND account_type = 'owner_payout' AND is_active = true LIMIT 1;
    IF v_owner_account_id IS NULL THEN
      INSERT INTO ledger_accounts (account_type, owner_user_id, currency) VALUES ('owner_payout', NEW.owner_id, COALESCE(NEW.currency, 'THB')) RETURNING id INTO v_owner_account_id;
    END IF;
    IF NEW.transaction_type = 'expense' THEN
      INSERT INTO ledger_entries (debit_account_id, credit_account_id, amount, currency, entry_type, description)
      VALUES (v_expense_account_id, v_owner_account_id, NEW.amount, COALESCE(NEW.currency, 'THB'), 'property_expense', COALESCE(NEW.description, 'Auto-synced'));
    ELSIF NEW.transaction_type = 'income' THEN
      INSERT INTO ledger_entries (debit_account_id, credit_account_id, amount, currency, entry_type, description)
      VALUES (v_owner_account_id, v_expense_account_id, NEW.amount, COALESCE(NEW.currency, 'THB'), 'property_income', COALESCE(NEW.description, 'Auto-synced'));
    END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.get_or_create_wallet(p_user_id uuid)
 RETURNS wallets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wallet public.wallets;
BEGIN
  SELECT * INTO v_wallet FROM public.wallets WHERE user_id = p_user_id;

  IF v_wallet IS NULL THEN
    INSERT INTO public.wallets (user_id, balance, currency)
    VALUES (p_user_id, 0, 'THB')
    RETURNING * INTO v_wallet;
  END IF;

  RETURN v_wallet;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_cashback_on_booking_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cashback_percentage numeric;
  v_cashback_amount numeric;
  v_wallet_id uuid;
  v_min_order numeric;
  v_max_cashback numeric;
  v_booking_type text;
BEGIN
  -- Only process if status changed to 'completed'
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
    -- Skip if no total amount
    IF NEW.total_amount IS NULL OR NEW.total_amount <= 0 THEN
      RETURN NEW;
    END IF;

    -- Get booking type for category-specific cashback
    v_booking_type := NEW.booking_type::text;

    -- Get cashback settings (category-specific or default)
    SELECT percentage, min_order_amount, max_cashback_amount
    INTO v_cashback_percentage, v_min_order, v_max_cashback
    FROM public.cashback_settings
    WHERE is_active = true AND (category = v_booking_type OR category = 'default')
    ORDER BY CASE WHEN category = v_booking_type THEN 0 ELSE 1 END
    LIMIT 1;

    -- Use default 5% if no settings found
    IF v_cashback_percentage IS NULL THEN
      v_cashback_percentage := 5;
      v_min_order := 0;
    END IF;

    -- Check minimum order amount
    IF NEW.total_amount < COALESCE(v_min_order, 0) THEN
      RETURN NEW;
    END IF;

    -- Calculate cashback amount
    v_cashback_amount := ROUND((NEW.total_amount * v_cashback_percentage / 100), 2);

    -- Apply max cashback limit if set
    IF v_max_cashback IS NOT NULL AND v_cashback_amount > v_max_cashback THEN
      v_cashback_amount := v_max_cashback;
    END IF;

    -- Skip if cashback is 0 or negative
    IF v_cashback_amount <= 0 THEN
      RETURN NEW;
    END IF;

    -- Get or create wallet
    SELECT id INTO v_wallet_id
    FROM public.wallets
    WHERE user_id = NEW.user_id;

    IF v_wallet_id IS NULL THEN
      INSERT INTO public.wallets (user_id, balance, currency)
      VALUES (NEW.user_id, 0, 'RUB')
      RETURNING id INTO v_wallet_id;
    END IF;

    -- Update wallet balance
    UPDATE public.wallets
    SET balance = balance + v_cashback_amount,
        updated_at = now()
    WHERE id = v_wallet_id;

    -- Create transaction record
    INSERT INTO public.wallet_transactions (
      wallet_id,
      user_id,
      type,
      amount,
      currency,
      description,
      description_ru,
      reference_type,
      reference_id,
      status
    ) VALUES (
      v_wallet_id,
      NEW.user_id,
      'cashback',
      v_cashback_amount,
      'RUB',
      'Cashback ' || v_cashback_percentage || '% for booking #' || LEFT(NEW.id::text, 8),
      'Кэшбэк ' || v_cashback_percentage || '% за бронирование #' || LEFT(NEW.id::text, 8),
      'booking',
      NEW.id::text,
      'completed'
    );

    -- Create notification about cashback
    INSERT INTO public.notifications (
      user_id,
      title,
      body,
      type,
      data,
      is_read
    ) VALUES (
      NEW.user_id,
      '💰 Кэшбэк начислен!',
      'Вам начислено ' || v_cashback_amount || ' ₽ кэшбэка (' || v_cashback_percentage || '%) за завершённое бронирование.',
      'cashback',
      jsonb_build_object(
        'amount', v_cashback_amount,
        'percentage', v_cashback_percentage,
        'booking_id', NEW.id
      ),
      false
    );

  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_referral_bonus()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_referral RECORD;
  v_settings RECORD;
  v_referrer_wallet_id UUID;
  v_referred_wallet_id UUID;
BEGIN
  -- Only process on first completed booking
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN

    -- Check if this user has a pending referral
    SELECT * INTO v_referral
    FROM public.referrals
    WHERE referred_id = NEW.user_id AND status = 'pending'
    LIMIT 1;

    IF v_referral IS NULL THEN
      RETURN NEW;
    END IF;

    -- Get settings for minimum amount check
    SELECT min_booking_amount INTO v_settings
    FROM public.referral_settings WHERE is_active = true LIMIT 1;

    -- Check minimum booking amount
    IF NEW.total_amount < COALESCE(v_settings.min_booking_amount, 0) THEN
      RETURN NEW;
    END IF;

    -- Get or create wallets for both users
    SELECT id INTO v_referrer_wallet_id FROM public.wallets WHERE user_id = v_referral.referrer_id;
    IF v_referrer_wallet_id IS NULL THEN
      INSERT INTO public.wallets (user_id, balance, currency)
      VALUES (v_referral.referrer_id, 0, 'THB')
      RETURNING id INTO v_referrer_wallet_id;
    END IF;

    SELECT id INTO v_referred_wallet_id FROM public.wallets WHERE user_id = v_referral.referred_id;
    IF v_referred_wallet_id IS NULL THEN
      INSERT INTO public.wallets (user_id, balance, currency)
      VALUES (v_referral.referred_id, 0, 'THB')
      RETURNING id INTO v_referred_wallet_id;
    END IF;

    -- Credit referrer bonus
    UPDATE public.wallets SET balance = balance + v_referral.referrer_bonus, updated_at = now()
    WHERE id = v_referrer_wallet_id;

    INSERT INTO public.wallet_transactions (wallet_id, user_id, type, amount, currency, description, description_ru, reference_type, reference_id, status)
    VALUES (v_referrer_wallet_id, v_referral.referrer_id, 'referral_bonus', v_referral.referrer_bonus, 'THB', 
            'Referral bonus for inviting a friend', 'Бонус за приглашённого друга', 'referral', v_referral.id::text, 'completed');

    -- Credit referred user bonus
    UPDATE public.wallets SET balance = balance + v_referral.referred_bonus, updated_at = now()
    WHERE id = v_referred_wallet_id;

    INSERT INTO public.wallet_transactions (wallet_id, user_id, type, amount, currency, description, description_ru, reference_type, reference_id, status)
    VALUES (v_referred_wallet_id, v_referral.referred_id, 'referral_bonus', v_referral.referred_bonus, 'THB',
            'Welcome bonus for using referral code', 'Приветственный бонус по реферальному коду', 'referral', v_referral.id::text, 'completed');

    -- Update referral status
    UPDATE public.referrals SET status = 'completed', bonus_paid_at = now()
    WHERE id = v_referral.id;

    -- Notify referrer
    INSERT INTO public.notifications (user_id, title, body, type, data, is_read)
    VALUES (v_referral.referrer_id, '🎉 Реферальный бонус!', 
            'Ваш друг совершил первый заказ! Вам начислено ฿' || v_referral.referrer_bonus,
            'referral', jsonb_build_object('amount', v_referral.referrer_bonus, 'referral_id', v_referral.id), false);

    -- Notify referred user
    INSERT INTO public.notifications (user_id, title, body, type, data, is_read)
    VALUES (v_referral.referred_id, '🎁 Приветственный бонус!',
            'Вам начислено ฿' || v_referral.referred_bonus || ' за использование реферального кода!',
            'referral', jsonb_build_object('amount', v_referral.referred_bonus, 'referral_id', v_referral.id), false);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_ledger_entries(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order RECORD;
  v_platform_account_id uuid;
  v_customer_account_id uuid;
  v_vendor_account_id uuid;
  v_mc_account_id uuid;
  v_platform_fee numeric;
  v_vendor_amount numeric;
  v_mc_commission numeric := 0;
  v_owner_amount numeric;
  v_property_id uuid;
  v_mc_id uuid;
  v_commission_rate numeric;
  v_commission_type text;
  v_commission_base text;
BEGIN
  -- Get order details
  SELECT id, total_amount, platform_fee_amount, customer_user_id, provider_org_id, currency
  INTO v_order
  FROM orders WHERE id = p_order_id;

  IF v_order IS NULL THEN
    RAISE EXCEPTION 'Order not found: %', p_order_id;
  END IF;

  -- Skip if ledger entries already exist (idempotent)
  IF EXISTS (SELECT 1 FROM ledger_entries WHERE order_id = p_order_id LIMIT 1) THEN
    RETURN;
  END IF;

  v_platform_fee := COALESCE(v_order.platform_fee_amount, ROUND(v_order.total_amount * 0.10, 2));
  v_vendor_amount := v_order.total_amount - v_platform_fee;

  -- Try to find property_id from order_items (for property orders)
  SELECT (oi.metadata->>'property_id')::uuid INTO v_property_id
  FROM order_items oi
  WHERE oi.order_id = p_order_id AND oi.item_type = 'property'
  LIMIT 1;

  -- If property found, look up MC and commission terms
  IF v_property_id IS NOT NULL THEN
    SELECT p.management_company_id INTO v_mc_id
    FROM properties p WHERE p.id = v_property_id;

    IF v_mc_id IS NOT NULL THEN
      -- Look up active management terms for this property
      SELECT pmt.commission_rate, pmt.commission_type, pmt.commission_base
      INTO v_commission_rate, v_commission_type, v_commission_base
      FROM property_management_terms pmt
      WHERE pmt.property_id = v_property_id
        AND pmt.status = 'active'
        AND (pmt.valid_from IS NULL OR pmt.valid_from <= CURRENT_DATE)
        AND (pmt.valid_until IS NULL OR pmt.valid_until >= CURRENT_DATE)
      ORDER BY pmt.created_at DESC
      LIMIT 1;

      -- Fallback to MC default commission if no property-level terms
      IF v_commission_rate IS NULL THEN
        SELECT mc.default_commission_rate INTO v_commission_rate
        FROM management_companies mc WHERE mc.id = v_mc_id;
        v_commission_type := 'percent';
        v_commission_base := 'net'; -- default: % of net (after platform fee)
      END IF;

      -- Calculate MC commission
      IF v_commission_rate IS NOT NULL AND v_commission_rate > 0 THEN
        IF v_commission_type = 'fixed' THEN
          v_mc_commission := LEAST(v_commission_rate, v_vendor_amount);
        ELSE
          -- percent type
          IF v_commission_base = 'gross' THEN
            v_mc_commission := ROUND(v_order.total_amount * (v_commission_rate / 100), 2);
          ELSE
            -- net (after platform fee)
            v_mc_commission := ROUND(v_vendor_amount * (v_commission_rate / 100), 2);
          END IF;
          v_mc_commission := LEAST(v_mc_commission, v_vendor_amount);
        END IF;
      END IF;
    END IF;
  END IF;

  v_owner_amount := v_vendor_amount - v_mc_commission;

  -- Get or create platform revenue account
  SELECT id INTO v_platform_account_id FROM ledger_accounts WHERE account_type = 'platform_revenue' LIMIT 1;
  IF v_platform_account_id IS NULL THEN
    INSERT INTO ledger_accounts (account_type, currency) VALUES ('platform_revenue', COALESCE(v_order.currency, 'THB'))
    RETURNING id INTO v_platform_account_id;
  END IF;

  -- Get or create customer account
  SELECT id INTO v_customer_account_id FROM ledger_accounts 
  WHERE owner_user_id = v_order.customer_user_id AND account_type = 'customer' LIMIT 1;
  IF v_customer_account_id IS NULL AND v_order.customer_user_id IS NOT NULL THEN
    INSERT INTO ledger_accounts (owner_user_id, account_type, currency) 
    VALUES (v_order.customer_user_id, 'customer', COALESCE(v_order.currency, 'THB'))
    RETURNING id INTO v_customer_account_id;
  END IF;

  -- Get or create vendor (owner) account
  IF v_order.provider_org_id IS NOT NULL THEN
    SELECT id INTO v_vendor_account_id FROM ledger_accounts
    WHERE owner_org_id = v_order.provider_org_id AND account_type = 'vendor_balance' LIMIT 1;
    IF v_vendor_account_id IS NULL THEN
      INSERT INTO ledger_accounts (owner_org_id, account_type, currency)
      VALUES (v_order.provider_org_id, 'vendor_balance', COALESCE(v_order.currency, 'THB'))
      RETURNING id INTO v_vendor_account_id;
    END IF;
  END IF;

  -- Use platform account as fallback for vendor if no provider
  IF v_vendor_account_id IS NULL THEN
    v_vendor_account_id := v_platform_account_id;
  END IF;

  -- Get or create MC balance account (if MC commission applies)
  IF v_mc_commission > 0 AND v_mc_id IS NOT NULL THEN
    SELECT id INTO v_mc_account_id FROM ledger_accounts
    WHERE management_company_id = v_mc_id AND account_type = 'mc_balance' LIMIT 1;
    IF v_mc_account_id IS NULL THEN
      INSERT INTO ledger_accounts (management_company_id, account_type, currency)
      VALUES (v_mc_id, 'mc_balance', COALESCE(v_order.currency, 'THB'))
      RETURNING id INTO v_mc_account_id;
    END IF;
  END IF;

  -- Entry 1: Platform fee (debit customer → credit platform)
  IF v_customer_account_id IS NOT NULL AND v_platform_fee > 0 THEN
    INSERT INTO ledger_entries (debit_account_id, credit_account_id, amount, currency, order_id, entry_type, description)
    VALUES (v_customer_account_id, v_platform_account_id, v_platform_fee, 
            COALESCE(v_order.currency, 'THB'), p_order_id, 'platform_fee',
            'Platform fee for order ' || p_order_id::text);
  END IF;

  -- Entry 2: Owner payment (debit customer → credit vendor/owner)
  IF v_customer_account_id IS NOT NULL AND v_owner_amount > 0 THEN
    INSERT INTO ledger_entries (debit_account_id, credit_account_id, amount, currency, order_id, entry_type, description)
    VALUES (v_customer_account_id, v_vendor_account_id, v_owner_amount,
            COALESCE(v_order.currency, 'THB'), p_order_id, 'vendor_payment',
            'Owner payment for order ' || p_order_id::text);
  END IF;

  -- Entry 3: MC commission (debit customer → credit MC) — only if MC has terms
  IF v_customer_account_id IS NOT NULL AND v_mc_commission > 0 AND v_mc_account_id IS NOT NULL THEN
    INSERT INTO ledger_entries (debit_account_id, credit_account_id, amount, currency, order_id, entry_type, description)
    VALUES (v_customer_account_id, v_mc_account_id, v_mc_commission,
            COALESCE(v_order.currency, 'THB'), p_order_id, 'mc_commission',
            'MC commission for order ' || p_order_id::text);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.topup_wallet_atomic(p_user_id uuid, p_amount numeric, p_reference_type text, p_reference_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wallet_id UUID;
  v_new_balance NUMERIC;
  v_currency TEXT;
  v_transaction_id UUID;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'invalid_wallet_amount' USING ERRCODE='22023'; END IF;
  -- Lock row and update atomically in single statement
  UPDATE public.wallets
  SET balance = balance + p_amount, updated_at = now()
  WHERE user_id = p_user_id
  RETURNING id, balance, currency INTO v_wallet_id, v_new_balance, v_currency;

  -- If wallet doesn't exist, create it
  IF v_wallet_id IS NULL THEN
    INSERT INTO public.wallets (user_id, balance, currency)
    VALUES (p_user_id, p_amount, 'THB')
    RETURNING id, balance, currency INTO v_wallet_id, v_new_balance, v_currency;
  END IF;

  -- Insert transaction record atomically
  INSERT INTO public.wallet_transactions (
    wallet_id, user_id, type, amount, currency,
    description, description_ru,
    reference_type, reference_id, status
  ) VALUES (
    v_wallet_id, p_user_id, 'topup', p_amount, v_currency,
    'Wallet top up via Stripe', 'Пополнение кошелька через Stripe',
    p_reference_type, p_reference_id, 'completed'
  )
  RETURNING id INTO v_transaction_id;

  RETURN jsonb_build_object(
    'success', true,
    'wallet_id', v_wallet_id,
    'new_balance', v_new_balance,
    'transaction_id', v_transaction_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_sync_order_item_to_property_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order orders;
BEGIN
  IF NEW.item_type <> 'property' THEN
    RETURN NEW;
  END IF;
  SELECT * INTO v_order FROM orders WHERE id = NEW.order_id;
  IF v_order.id IS NULL OR v_order.vertical <> 'property' THEN
    RETURN NEW;
  END IF;
  -- Reuse the order-level sync by performing a no-op update touch
  UPDATE orders SET updated_at = now() WHERE id = NEW.order_id;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_sync_order_to_property_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_property_id uuid; v_owner_id uuid; v_guest_name text; v_guest_phone text; v_guest_email text;
  v_guests_count int; v_check_in date; v_check_out date; v_status text; v_source text; v_item_meta jsonb;
  v_deposit numeric;
BEGIN
  IF COALESCE(NEW.vertical, OLD.vertical) <> 'property' THEN RETURN NEW; END IF;
  SELECT COALESCE(oi.resource_id::uuid, (oi.metadata->>'property_id')::uuid), oi.metadata
    INTO v_property_id, v_item_meta
  FROM order_items oi WHERE oi.order_id = NEW.id AND oi.item_type = 'property' LIMIT 1;
  IF v_property_id IS NULL THEN RETURN NEW; END IF;
  SELECT owner_id INTO v_owner_id FROM properties WHERE id = v_property_id;
  SELECT name, phone, email INTO v_guest_name, v_guest_phone, v_guest_email
  FROM order_participants WHERE order_id = NEW.id AND role IN ('guest','primary')
    ORDER BY (role = 'guest') DESC LIMIT 1;
  v_check_in := (NEW.start_at::timestamptz)::date;
  v_check_out := (NEW.end_at::timestamptz)::date;
  v_guests_count := COALESCE(NULLIF(NEW.metadata->>'guests_count','')::int,
    NULLIF(NEW.metadata->>'guests','')::int, NULLIF(v_item_meta->>'guests','')::int, 1);
  v_deposit := NULLIF(COALESCE(NEW.metadata->>'deposit_amount', v_item_meta->>'deposit_amount'),'')::numeric;
  v_source := COALESCE(NULLIF(NEW.metadata->>'source', ''), 'manual');
  v_status := CASE
    WHEN NEW.deleted_at IS NOT NULL THEN 'cancelled'
    WHEN NEW.status IN ('cancelled','refunded','expired') THEN 'cancelled'
    -- Preserve lifecycle labels without implicitly releasing no-show inventory.
    WHEN NEW.status IN ('confirmed','completed','checked_in','checked_out','no_show') THEN NEW.status::text
    ELSE 'pending' END;
  UPDATE property_bookings SET external_id = NEW.id::text
  WHERE external_id IS NULL AND property_id = v_property_id
    AND check_in = v_check_in AND check_out = v_check_out
    AND NOT EXISTS (SELECT 1 FROM property_bookings pb2 WHERE pb2.external_id = NEW.id::text);
  BEGIN
    INSERT INTO property_bookings (property_id, owner_id, guest_name, guest_phone, guest_email,
      guests_count, check_in, check_out, total_amount, currency, source, external_id, status, notes,
      deposit_amount, created_at, updated_at)
    VALUES (v_property_id, v_owner_id, COALESCE(v_guest_name,'Guest'), v_guest_phone, v_guest_email,
      v_guests_count, v_check_in, v_check_out, NEW.total_amount, NEW.currency, v_source, NEW.id::text, v_status, NEW.notes,
      v_deposit, NEW.created_at, NEW.updated_at)
    ON CONFLICT (external_id) DO UPDATE SET
      property_id = EXCLUDED.property_id, owner_id = EXCLUDED.owner_id, guest_name = EXCLUDED.guest_name,
      guest_phone = EXCLUDED.guest_phone, guest_email = EXCLUDED.guest_email, guests_count = EXCLUDED.guests_count,
      check_in = EXCLUDED.check_in, check_out = EXCLUDED.check_out, total_amount = EXCLUDED.total_amount,
      currency = EXCLUDED.currency, status = EXCLUDED.status, notes = EXCLUDED.notes,
      deposit_amount = COALESCE(EXCLUDED.deposit_amount, property_bookings.deposit_amount), updated_at = now();
  EXCEPTION WHEN exclusion_violation THEN
    INSERT INTO reconciliation_alerts (alert_type, severity, order_id, expected_amount, currency, description, details)
    SELECT 'booking_overlap', 'high', NEW.id, NEW.total_amount, NEW.currency,
      'Order dates overlap an existing booking for this property',
      jsonb_build_object('property_id', v_property_id, 'check_in', v_check_in, 'check_out', v_check_out)
    WHERE NOT EXISTS (SELECT 1 FROM reconciliation_alerts ra WHERE ra.order_id = NEW.id AND ra.alert_type = 'booking_overlap' AND ra.resolved_at IS NULL);
  END;
  RETURN NEW;
END;
$function$
